    var pid=one(ba.property);if(!pid)continue;
    var ci=dayDiff(ba.check_in),co=dayDiff(ba.check_out);
    if(co!=null&&co>=0&&co<=7)(outBy[pid+'|'+co]=outBy[pid+'|'+co]||[]).push(b);
    if(ci!=null&&ci>=0&&ci<=7)(inBy[pid+'|'+ci]=inBy[pid+'|'+ci]||[]).push({i:b,d:ba.check_in});}
  var flips=[];
